    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, #fff7eb 0, transparent 30%),
        linear-gradient(180deg, #f7f4ef 0%, #f2ede5 100%);
      color: var(--text);
      line-height: 1.5;
    }

    img {
      max-width: 100%;
      display: block;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    a:hover,
    a:focus-visible,
    button:hover,
    button:focus-visible {
      outline: none;
    }

    :focus-visible {
      outline: 3px solid #0f5fd0;
      outline-offset: 3px;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 1000;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      border: 2px solid var(--brand);
      transform: translateY(-180%);
      transition: transform 0.2s ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page-shell {
      width: min(100% - 2rem, var(--content-max));
      margin: 0 auto;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 50;
      backdrop-filter: blur(10px);
      background: rgba(245, 243, 239, 0.88);
      border-bottom: 1px solid rgba(217, 210, 199, 0.75);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 0;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      font-weight: 800;
      letter-spacing: 0.02em;
      color: var(--brand);
    }

    .brand-mark {
      width: 2.5rem;
      aspect-ratio: 1;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--brand), #335f86);
      display: grid;
      place-items: center;
      color: #fff;
      font-size: 1rem;
      box-shadow: var(--shadow);
    }

    nav ul {
      list-style: none;
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      margin: 0;
      padding: 0;
    }

    nav a {
      color: var(--muted);
      font-weight: 600;
    }

    nav a:hover {
      color: var(--text);
    }

    .cart-pill {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      border: 1px solid var(--line);
      box-shadow: 0 8px 20px rgba(31, 35, 40, 0.06);
      font-weight: 700;
    }

    main {
      padding: 1.25rem 0 4rem;
    }

    .hero {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 1.5rem;
      align-items: stretch;
      margin-top: 1rem;
    }

    .hero-copy,
    .hero-aside,
    .section-card {
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.5rem, 3vw, 3rem);
      min-width: 0;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.4rem 0.75rem;
      border-radius: 999px;
      background: #f5ebda;
      color: #7b4f11;
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    h1 {
      margin: 1rem 0 0.75rem;
      font-size: clamp(2.4rem, 5vw, 4.8rem);
      line-height: 0.96;
      letter-spacing: -0.04em;
      max-width: 12ch;
      color: var(--brand);
    }

    .hero-copy p {
      max-width: 56ch;
      margin: 0;
      color: var(--muted);
      font-size: 1.0625rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.9rem;
      margin-top: 1.5rem;
    }

    .button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.25rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.18s ease, box-shadow 0.18s ease, background-color 0.18s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-primary {
      background: var(--brand);
      color: #fff;
      box-shadow: 0 10px 24px rgba(23, 50, 77, 0.18);
    }

    .button-secondary {
      background: #efe8dc;
      color: var(--brand);
      border: 1px solid var(--line);
    }

    .hero-metrics {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
      margin-top: 1.75rem;
    }

    .metric {
      min-width: 0;
      padding-top: 1rem;
      border-top: 1px solid var(--line);
    }

    .metric strong {
      display: block;
      font-size: 1.4rem;
      color: var(--brand);
    }

    .metric span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .hero-aside {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
      min-width: 0;
    }

    .deal-feature {
      padding: 1.25rem;
      border-radius: var(--radius-lg);
      background: linear-gradient(180deg, #1d3a56 0%, #294d72 100%);
      color: #fff;
      min-width: 0;
    }

    .deal-feature h2 {
      margin: 0.25rem 0 0.5rem;
      font-size: 1.45rem;
    }

    .deal-feature p {
      margin: 0 0 1rem;
      color: #e8eef5;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.5rem;
      margin: 0;
    }

    .countdown div {
      padding: 0.75rem 0.5rem;
      border-radius: var(--radius-sm);
      background: rgba(255, 255, 255, 0.12);
      text-align: center;
    }

    .countdown strong {
      display: block;
      font-size: 1.3rem;
    }

    .countdown span {
      font-size: 0.78rem;
      text-transform: uppercase;
      letter-spacing: 0.06em;
    }

    .side-note {
      padding: 1rem 1.1rem;
      border-radius: var(--radius-lg);
      background: #f3efe8;
      border: 1px solid var(--line);
    }

    .side-note h2,
    .section-heading h2 {
      margin: 0;
      font-size: 1.55rem;
      color: var(--brand);
    }

    .side-note p {
      margin: 0.45rem 0 0;
      color: var(--muted);
    }

    .section-block {
      margin-top: 1.5rem;
    }

    .section-heading {
      display: flex;
      flex-wrap: wrap;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-heading p {
      margin: 0;
      color: var(--muted);
      max-width: 58ch;
    }

    .filter-group {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

    .filter-btn {
      border: 1px solid var(--line);
      background: var(--surface);
      color: var(--brand);
      padding: 0.65rem 0.95rem;
      border-radius: 999px;
      font-weight: 700;
      cursor: pointer;
    }

    .filter-btn[aria-pressed="true"] {
      background: var(--brand);
      color: #fff;
      border-color: var(--brand);
    }

    .products-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card,
    .editorial-card {
      min-width: 0;
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: 0 14px 30px rgba(31, 35, 40, 0.06);
    }

    .product-media {
      aspect-ratio: 4 / 3;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at 30% 25%, #fff 0, #fff 12%, transparent 13%),
        linear-gradient(135deg, #f5d6a5 0%, #efb166 100%);
      color: var(--brand);
      font-size: 4rem;
    }

    .product-content {
      padding: 1rem;
    }

    .product-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.5rem;
      margin-bottom: 0.65rem;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      padding: 0.28rem 0.55rem;
      border-radius: 999px;
      background: #eff5f0;
      color: var(--accent);
      font-size: 0.8rem;
      font-weight: 700;
    }

    .product-card h3 {
      margin: 0 0 0.55rem;
      font-size: 1.1rem;
      color: var(--brand);
    }

    .product-card p {
      margin: 0 0 0.9rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
    }

    .price {
      font-size: 1.12rem;
      font-weight: 800;
      color: var(--text);
    }

    .small-button {
      padding: 0.68rem 0.92rem;
      border-radius: 999px;
      border: 1px solid var(--brand);
      background: var(--brand);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
    }

    .deals-grid,
    .editorial-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1rem;
    }

    .deal-card {
      padding: 1.2rem;
      border-radius: var(--radius-lg);
      border: 1px solid var(--line);
      background: linear-gradient(180deg, #fff 0%, #faf6f0 100%);
    }

    .deal-card strong {
      display: inline-flex;
      margin-bottom: 0.5rem;
      color: var(--accent);
    }

    .deal-card h3 {
      margin: 0 0 0.4rem;
      color: var(--brand);
      font-size: 1.25rem;
    }

    .deal-card p {
      margin: 0 0 1rem;
      color: var(--muted);
    }

    .deal-card ul {
      margin: 0;
      padding-left: 1.1rem;
      color: var(--text);
    }

    .editorial-card figure {
      margin: 0;
    }

    .editorial-card .editorial-media {
      aspect-ratio: 16 / 9;
      background:
        linear-gradient(135deg, #d9e6f1 0%, #f6f0e4 100%);
      display: grid;
      place-items: center;
      color: var(--brand);
      font-size: 3rem;
    }

    .editorial-content {
      padding: 1.1rem;
    }

    .editorial-content h3 {
      margin: 0 0 0.5rem;
      color: var(--brand);
      font-size: 1.15rem;
    }

    .editorial-content p {
      margin: 0 0 1rem;
      color: var(--muted);
    }

    .meta-row {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      align-items: center;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .meta-row .read-more {
      color: var(--brand);
      font-weight: 700;
    }

    .status-message {
      margin: 1rem 0 0;
      min-height: 1.5rem;
      color: var(--brand);
      font-weight: 700;
    }

    footer {
      padding: 2rem 0 3rem;
      color: var(--muted);
    }

    .footer-inner {
      border-top: 1px solid var(--line);
      padding-top: 1.5rem;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    @media (max-width: 980px) {
      .hero,
      .products-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .hero {
        grid-template-columns: 1fr;
      }

      .hero-aside {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 700px) {
      .header-inner,
      .section-heading,
      .footer-inner,
      .product-footer {
        flex-direction: column;
        align-items: flex-start;
      }

      nav ul {
        gap: 0.75rem 1rem;
      }

      .hero-metrics,
      .countdown,
      .deals-grid,
      .editorial-grid,
      .products-grid,
      .hero-aside {
        grid-template-columns: 1fr;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --line: ButtonBorder;
        --brand: LinkText;
        --brand-2: LinkText;
        --accent: LinkText;
      }

      .button,
      .small-button,
      .filter-btn,
      .cart-pill,
      .hero-copy,
      .hero-aside,
      .section-card,
      .product-card,
      .editorial-card,
      .deal-card {
        forced-color-adjust: auto;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <header>
    <div class="page-shell header-inner">
      <a class="brand" href="#main" aria-label="Northstar Retail home">
        <span class="brand-mark" aria-hidden="true">N</span>
        Northstar Retail
      </a>

      <nav aria-label="Primary">
        <ul>
          <li><a href="#featured">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Editorial</a></li>
        </ul>
      </nav>

      <div class="cart-pill" aria-live="polite">
        Bag <strong id="cartCount">0</strong>
      </div>
    </div>
  </header>

  <main id="main">
    <div class="page-shell">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero-copy">
          <span class="eyebrow">Spring collection</span>
          <h1 id="hero-title">Everyday essentials, elevated for modern living.</h1>
          <p>
            Discover thoughtful home goods, wearable staples, and design-led accessories curated for a clean, calm retail experience.
          </p>
          <div class="hero-actions">
            <a class="button button-primary" href="#featured">Shop featured products</a>
            <a class="button button-secondary" href="#deals">See today's deals</a>
          </div>
          <div class="hero-metrics" aria-label="Store highlights">
            <div class="metric">
              <strong>120+</strong>
              <span>new arrivals</span>
            </div>
            <div class="metric">
              <strong>2-day</strong>
              <span>shipping on orders over $75</span>
            </div>
            <div class="metric">
              <strong>4.8/5</strong>
              <span>average customer rating</span>
            </div>
          </div>
        </div>

        <aside class="hero-aside" aria-label="Featured promotions">
          <div class="deal-feature">
            <span class="eyebrow">Limited time</span>
            <h2>Save 25% on outdoor layers</h2>
            <p>Lightweight outerwear and travel-ready essentials, priced for the first warm weekends.</p>
            <div class="countdown" aria-label="Deal countdown">
              <div><strong id="days">00</strong><span>Days</span></div>
              <div><strong id="hours">00</strong><span>Hours</span></div>
              <div><strong id="minutes">00</strong><span>Minutes</span></div>
              <div><strong id="seconds">00</strong><span>Seconds</span></div>
            </div>
          </div>

          <div class="side-note">
            <h2>Curated by our editors</h2>
            <p>Soft textures, durable materials, and a neutral palette make every pick easy to style and easier to keep.</p>
          </div>
        </aside>
      </section>

      <section class="section-block section-card" id="featured" aria-labelledby="featured-title" style="padding: 1.25rem;">
        <div class="section-heading">
          <div>
            <span class="eyebrow">Featured products</span>
            <h2 id="featured-title">Best sellers worth adding to your cart</h2>
            <p>Filter by category to find the right essentials for home, travel, and everyday wear.</p>
          </div>
          <div class="filter-group" role="group" aria-label="Product filters">
            <button class="filter-btn" type="button" aria-pressed="true" data-filter="all">All</button>
            <button class="filter-btn" type="button" aria-pressed="false" data-filter="home">Home</button>
            <button class="filter-btn" type="button" aria-pressed="false" data-filter="travel">Travel</button>
            <button class="filter-btn" type="button" aria-pressed="false" data-filter="wear">Wear</button>
          </div>
        </div>

        <div class="products-grid" id="productGrid">
          <article class="product-card" data-category="home">
            <div class="product-media" aria-hidden="true">◌</div>
            <div class="product-content">
              <div class="product-meta">
                <span class="tag">Home</span>
                <span>4.9 ★</span>
              </div>
              <h3>Meridian Throw</h3>
              <p>Woven with a cloud-soft finish for evenings in and a tailored look on the sofa.</p>
              <div class="product-footer">
                <span class="price">$68</span>
                <button class="small-button add-to-bag" type="button" data-name="Meridian Throw">Quick add</button>
              </div>
            </div>
          </article>

          <article class="product-card" data-category="wear">
            <div class="product-media" aria-hidden="true">◔</div>
            <div class="product-content">
              <div class="product-meta">
                <span class="tag">Wear</span>
                <span>4.8 ★</span>
              </div>
              <h3>Studio Knit Polo</h3>
              <p>Breathable, polished, and cut for easy layering from desk to dinner.</p>
              <div class="product-footer">
                <span class="price">$54</span>
                <button class="small-button add-to-bag" type="button" data-name="Studio Knit Polo">Quick add</button>
              </div>
            </div>
          </article>

          <article class="product-card" data-category="travel">
            <div class="product-media" aria-hidden="true">◫</div>
            <div class="product-content">
              <div class="product-meta">
                <span class="tag">Travel</span>
                <span>4.7 ★</span>
              </div>
              <h3>Weekender Tote</h3>
              <p>Structured storage with room for a laptop, shoes, and a long weekend's essentials.</p>
              <div class="product-footer">
                <span class="price">$82</span>
                <button class="small-button add-to-bag" type="button" data-name="Weekender Tote">Quick add</button>
              </div>
            </div>
          </article>

          <article class="product-card" data-category="home">
            <div class="product-media" aria-hidden="true">◐</div>
            <div class="product-content">
              <div class="product-meta">
                <span class="tag">Home</span>
                <span>4.9 ★</span>
              </div>
              <h3>Atlas Lamp</h3>
              <p>Warm, dimmable light with a minimal silhouette that anchors any room.</p>
              <div class="product-footer">
                <span class="price">$118</span>
                <button class="small-button add-to-bag" type="button" data-name="Atlas Lamp">Quick add</button>
              </div>
            </div>
          </article>
        </div>

        <p class="status-message" id="statusMessage" aria-live="polite"></p>
      </section>

      <section class="section-block" id="deals" aria-labelledby="deals-title">
        <div class="section-heading">
          <div>
            <span class="eyebrow">Deals</span>
            <h2 id="deals-title">Daily offers with clear value</h2>
            <p>Promotions built for simple browsing: fast to scan, easy to compare, and straightforward to buy.</p>
          </div>
        </div>

        <div class="deals-grid">
          <article class="deal-card">
            <strong>Editor's pick</strong>
            <h3>Buy 2, save 15% on bath accessories</h3>
            <p>Bundle towels, mats, and storage pieces to refresh the room in one go.</p>
            <ul>
              <li>Discount applied at checkout</li>
              <li>Mix textures and colors freely</li>
              <li>Ends tonight at midnight</li>
            </ul>
          </article>

          <article class="deal-card">
            <strong>Member favorite</strong>
            <h3>Free shipping on all weekend orders</h3>
            <p>Stock up on wardrobe staples and small home upgrades without the extra fee.</p>
            <ul>
              <li>No code required</li>
              <li>Applies automatically</li>
              <li>Available through Sunday</li>
            </ul>
          </article>
        </div>
      </section>

      <section class="section-block" id="editorial" aria-labelledby="editorial-title">
        <div class="section-heading">
          <div>
            <span class="eyebrow">Editorial</span>
            <h2 id="editorial-title">Stories that shape the collection</h2>
            <p>Short reads from the style desk covering materials, seasonal edits, and practical product inspiration.</p>
          </div>
        </div>

        <div class="editorial-grid">
          <article class="editorial-card">
            <figure>
              <div class="editorial-media" aria-hidden="true">✦</div>
              <figcaption class="editorial-content">
                <h3>The neutral palette guide</h3>
                <p>How warm beiges, slate blues, and olive accents make a home feel grounded without feeling flat.</p>
                <div class="meta-row">
                  <span>5 min read</span>
                  <span class="read-more">Read more</span>
                </div>
              </figcaption>
            </figure>
          </article>

          <article class="editorial-card">
            <figure>
              <div class="editorial-media" aria-hidden="true">☼</div>
              <figcaption class="editorial-content">
                <h3>Travel light, pack smart</h3>
                <p>A compact packing system built around flexible layers, durable fabric, and one versatile bag.</p>
                <div class="meta-row">
                  <span>4 min read</span>
                  <span class="read-more">Read more</span>
                </div>
              </figcaption>
            </figure>
          </article>
        </div>
      </section>
    </div>
  </main>

  <footer>
    <div class="page-shell footer-inner">
      <p>Northstar Retail — modern essentials for home, travel, and everyday wear.</p>
      <p>Built with plain HTML, CSS, and vanilla JavaScript.</p>
    </div>
  </footer>

  <script>
    const filters = Array.from(document.querySelectorAll('.filter-btn'));
    const products = Array.from(document.querySelectorAll('.product-card'));
    const statusMessage = document.getElementById('statusMessage');
    const cartCount = document.getElementById('cartCount');
    const addButtons = Array.from(document.querySelectorAll('.add-to-bag'));
    const countdownEls = {
      days: document.getElementById('days'),
      hours: document.getElementById('hours'),
      minutes: document.getElementById('minutes'),
      seconds: document.getElementById('seconds')
    };

    let bagCount = 0;
    const dealEnd = new Date();
    dealEnd.setHours(dealEnd.getHours() + 18);

    function updateCountdown() {
      const now = new Date();
      const remaining = Math.max(dealEnd - now, 0);
      const days = Math.floor(remaining / 86400000);
      const hours = Math.floor((remaining % 86400000) / 3600000);
      const minutes = Math.floor((remaining % 3600000) / 60000);
      const seconds = Math.floor((remaining % 60000) / 1000);

      countdownEls.days.textContent = String(days).padStart(2, '0');
      countdownEls.hours.textContent = String(hours).padStart(2, '0');
      countdownEls.minutes.textContent = String(minutes).padStart(2, '0');
      countdownEls.seconds.textContent = String(seconds).padStart(2, '0');
    }

    function applyFilter(filterValue) {
      filters.forEach((button) => {
        const pressed = button.dataset.filter === filterValue;
        button.setAttribute('aria-pressed', String(pressed));
      });

      products.forEach((card) => {
        const visible = filterValue === 'all' || card.dataset.category === filterValue;
        card.hidden = !visible;
      });

      const visibleCount = products.filter((card) => !card.hidden).length;
      statusMessage.textContent = `${visibleCount} product${visibleCount === 1 ? '' : 's'} shown for ${filterValue === 'all' ? 'all categories' : filterValue}.`;
    }

    filters.forEach((button) => {
      button.addEventListener('click', () => {
        applyFilter(button.dataset.filter);
      });
    });

    addButtons.forEach((button) => {
      button.addEventListener('click', () => {
        bagCount += 1;
        cartCount.textContent = String(bagCount);
        statusMessage.textContent = `${button.dataset.name} added to your bag.`;
      });
    });

    applyFilter('all');
    updateCountdown();
    window.setInterval(updateCountdown, 1000);
  </script>
