  <script>
    const filters = Array.from(document.querySelectorAll('.filter-btn'));
    const products = Array.from(document.querySelectorAll('.product-card'));
    const statusMessage = document.getElementById('statusMessage');
    const cartCount = document.getElementById('cartCount');
    const addButtons = Array.from(document.querySelectorAll('.add-to-bag'));
    const countdownEls = {
      days: document.getElementById('days'),
      hours: document.getElementById('hours'),
      minutes: document.getElementById('minutes'),
      seconds: document.getElementById('seconds')
    };

    let bagCount = 0;
    const dealEnd = new Date();
    dealEnd.setHours(dealEnd.getHours() + 18);

    function updateCountdown() {
      const now = new Date();
      const remaining = Math.max(dealEnd - now, 0);
      const days = Math.floor(remaining / 86400000);
      const hours = Math.floor((remaining % 86400000) / 3600000);
      const minutes = Math.floor((remaining % 3600000) / 60000);
      const seconds = Math.floor((remaining % 60000) / 1000);

      countdownEls.days.textContent = String(days).padStart(2, '0');
      countdownEls.hours.textContent = String(hours).padStart(2, '0');
      countdownEls.minutes.textContent = String(minutes).padStart(2, '0');
      countdownEls.seconds.textContent = String(seconds).padStart(2, '0');
    }

    function applyFilter(filterValue) {
      filters.forEach((button) => {
        const pressed = button.dataset.filter === filterValue;
        button.setAttribute('aria-pressed', String(pressed));
      });

      products.forEach((card) => {
        const visible = filterValue === 'all' || card.dataset.category === filterValue;
        card.hidden = !visible;
      });

      const visibleCount = products.filter((card) => !card.hidden).length;
      statusMessage.textContent = `${visibleCount} product${visibleCount === 1 ? '' : 's'} shown for ${filterValue === 'all' ? 'all categories' : filterValue}.`;
    }

    filters.forEach((button) => {
      button.addEventListener('click', () => {
        applyFilter(button.dataset.filter);
      });
    });

    addButtons.forEach((button) => {
      button.addEventListener('click', () => {
        bagCount += 1;
        cartCount.textContent = String(bagCount);
        statusMessage.textContent = `${button.dataset.name} added to your bag.`;
      });
    });

    applyFilter('all');
    updateCountdown();
    window.setInterval(updateCountdown, 1000);
  </script>
